package com.franco.desco.adapter.out.sqlserver.evaluation;import com.franco.desco.adapter.out.sqlserver.shared.*;import com.franco.desco.application.evaluation.*;import com.franco.desco.application.evaluation.port.out.EvaluationPersistencePort;import com.franco.desco.application.shared.*;import com.franco.desco.application.shared.pagination.PageResult;import com.franco.desco.domain.evaluation.EvaluationModels;import org.springframework.jdbc.core.simple.SimpleJdbcCall;import org.springframework.stereotype.Component;import java.util.*;
@Component public class EvaluationSqlServerAdapter implements EvaluationPersistencePort{private final SqlServerPaExecutor e;private final PaPayloadFactory pf;private final SimpleJdbcCall list,get,create,update,dry;public EvaluationSqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory pf){this.e=e;this.pf=pf;list=f.callWithResultSets("campo","PA_EvaluacionAgronomica_Sel_Listado","items");get=f.callWithResultSets("campo","PA_EvaluacionAgronomica_Sel_Detalle","header","files");create=f.call("campo","PA_EvaluacionAgronomica_Ins_Registro");update=f.call("campo","PA_EvaluacionAgronomica_Upd_Registro");dry=f.call("campo","PA_EvaluacionMateriaSeca_Ins_Registro");}
 public PersistenceResult<PageResult<EvaluationModels.Summary>>list(EvaluationCommands.ListEvaluations c,SessionIdentity i,RequestMetadata m){var pg=c.page();var f=pg.filtros();var payload=pf.forQuery(i,m,Map.of("filtros",map("pagina",pg.pagina(),"tamanoPagina",pg.tamanio(),"visitaTecnicaId",f==null?null:f.visitaTecnicaId(),"parcelaCultivoId",f==null?null:f.parcelaCultivoId(),"tipoEvaluacionId",f==null?null:f.tipoEvaluacionId(),"fechaDesde",f==null?null:f.fechaDesde(),"fechaHasta",f==null?null:f.fechaHasta())));var out=e.executeJson(list,payload);return PaAdapterSupport.page(out,rows(out,"items"),pg.pagina(),pg.tamanio(),this::summary,"No se pudieron consultar las evaluaciones.");}
 public PersistenceResult<EvaluationModels.Detail>get(EvaluationCommands.Get c,SessionIdentity i,RequestMetadata m){var out=e.executeJson(get,pf.forQuery(i,m,Map.of("evaluacion",Map.of("evaluacionAgronomicaId",c.evaluacionAgronomicaId()))));if(!PaAdapterSupport.success(out))return PersistenceResult.error(PaAdapterSupport.message(out,"No se pudo consultar la evaluación."));var h=one(out,"header");if(h==null)return PersistenceResult.error("La evaluación seleccionada no está disponible.");return PersistenceResult.ok(PaAdapterSupport.message(out,"Evaluación consultada correctamente."),new EvaluationModels.Detail(summary(h),SqlValues.longValue(h,"parcelaId"),SqlValues.string(h,"codigoParcela"),SqlValues.string(h,"parcela"),SqlValues.string(h,"variedad"),rows(out,"files").stream().map(this::file).toList()));}
 public PersistenceResult<Long>create(EvaluationCommands.Create c,SessionIdentity i,RequestMetadata m){var p=new LinkedHashMap<String,Object>();p.put("evaluacion",map("visitaTecnicaId",c.visitaTecnicaId(),"parcelaCultivoId",c.parcelaCultivoId(),"tipoEvaluacionId",c.tipoEvaluacionId(),"fechaHora",c.fechaHora(),"resultado",c.resultado(),"observacion",c.observacion()));if(c.materiaSeca()!=null)p.put("materiaSeca",dryMap(c.materiaSeca().porcentajeMateriaSeca(),c.materiaSeca().numeroMuestras()));var out=e.executeJson(create,pf.forWrite(i,m,c,p));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nEvaluacionAgronomicaId"),"No se pudo registrar la evaluación.");}
 public PersistenceResult<Void>update(EvaluationCommands.Update c,SessionIdentity i,RequestMetadata m){var p=new LinkedHashMap<String,Object>();p.put("evaluacion",map("evaluacionAgronomicaId",c.evaluacionAgronomicaId(),"parcelaCultivoId",c.parcelaCultivoId(),"tipoEvaluacionId",c.tipoEvaluacionId(),"fechaHora",c.fechaHora(),"resultado",c.resultado(),"observacion",c.observacion()));if(c.materiaSeca()!=null)p.put("materiaSeca",dryMap(c.materiaSeca().porcentajeMateriaSeca(),c.materiaSeca().numeroMuestras()));return PaAdapterSupport.result(e.executeJson(update,pf.forWrite(i,m,c,p)),null,"No se pudo actualizar la evaluación.");}
 public PersistenceResult<Void>registerDryMatter(EvaluationCommands.RegisterDryMatter c,SessionIdentity i,RequestMetadata m){return PaAdapterSupport.result(e.executeJson(dry,pf.forWrite(i,m,c,Map.of("materiaSeca",dryMap(c.porcentajeMateriaSeca(),c.numeroMuestras(),c.evaluacionAgronomicaId())))),null,"No se pudo registrar materia seca.");}
 private Map<String,Object>dryMap(Object...v){if(v.length==3)return map("evaluacionAgronomicaId",v[2],"porcentajeMateriaSeca",v[0],"numeroMuestras",v[1]);return map("porcentajeMateriaSeca",v[0],"numeroMuestras",v[1]);}private EvaluationModels.Summary summary(Map<String,Object>r){return new EvaluationModels.Summary(SqlValues.longValue(r,"evaluacionAgronomicaId"),SqlValues.longValue(r,"visitaTecnicaId"),SqlValues.longValue(r,"parcelaCultivoId"),SqlValues.intValue(r,"tipoEvaluacionId"),SqlValues.string(r,"codigoTipoEvaluacion"),SqlValues.string(r,"tipoEvaluacion"),SqlValues.instant(r,"fechaHora"),SqlValues.string(r,"resultado"),SqlValues.string(r,"observacion"),SqlValues.decimal(r,"porcentajeMateriaSeca"),SqlValues.intValue(r,"numeroMuestras"),SqlValues.longValue(r,"predioId"),SqlValues.string(r,"codigoPredio"),SqlValues.string(r,"predio"));}private EvaluationModels.File file(Map<String,Object>r){return new EvaluationModels.File(SqlValues.longValue(r,"archivoId"),SqlValues.string(r,"nombreOriginal"),SqlValues.string(r,"mimeType"),SqlValues.longValue(r,"tamanoBytes"),SqlValues.string(r,"secureUrl"),SqlValues.string(r,"categoria"),SqlValues.string(r,"origenCaptura"),SqlValues.instant(r,"fechaCarga"));}private List<Map<String,Object>>rows(Map<String,Object>o,String k){return new PaResultSets(o).rows(k);}private Map<String,Object>one(Map<String,Object>o,String k){return new PaResultSets(o).one(k).orElse(null);}private static Map<String,Object>map(Object...v){Map<String,Object>m=new LinkedHashMap<>();for(int n=0;n<v.length;n+=2)if(v[n+1]!=null)m.put((String)v[n],v[n+1]);return m;}}
